function masLargoSinRepetir(s) {
  const ultimo = new Map();
  let izq = 0, mejor = 0;
  for (let der = 0; der < s.length; der++) {
    const c = s[der];
    if (ultimo.has(c)) izq = Math.max(izq, ultimo.get(c) + 1);
    ultimo.set(c, der);
    mejor = Math.max(mejor, der - izq + 1);
  }
  return mejor;
}

solution.python:
def masLargoSinRepetir(s):
    ultimo = {}
    izq = mejor = 0
    for der, c in enumerate(s):
        if c in ultimo:
            izq = max(izq, ultimo[c] + 1)
        ultimo[c] = der
        mejor = max(mejor, der - izq + 1)
    return mejor
